    {
      "card_ids": ["C40"],
      "claim": "Doxylamine, a close antihistamine analogue with the same phenyl(2-pyridyl) center and a basic amine, has about 50% oral bioavailability, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Imidafenacin, containing a phenyl/heteroaryl-substituted quaternary carbon and basic amine, has an absolute oral bioavailability of 57.8%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Bepotastine, a pyridyl-phenyl piperidine, has >80% oral bioavailability in humans, supporting high F for the query's similar lipophilic amine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Fexofenadine, a piperidine diaryl-carbinol analogue, has about 33% absolute oral bioavailability, still above the 20% threshold despite P-gp and polar acid liabilities.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Ebastine, a lipophilic piperidine with diaryl ether and butyrophenone features, achieves about 40% oral bioavailability, supporting high F for a lipophilic piperidine query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Terfenadine has <5% oral bioavailability, but this contradictory low value is driven by extensive CYP3A4 first-pass metabolism to fexofenadine; the query lacks the tert-butylphenol oxidation site, so this liability transfers poorly.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C01"],
      "claim": "(R)-Oxybutynin has about 6.7% oral bioavailability, but this low value is tied to ester hydrolysis and N-deethylation; the query has no ester and a hindered 2,6-dimethylpiperidine instead of diethylamine, reducing transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high: the query is a lipophilic, permeable tertiary amine with a phenyl/2-pyridyl carbinol and hindered piperidine. Most close analogues with these features have F values of 33-80%, while the low-F analogues (terfenadine, oxybutynin) owe their poor bioavailability to specific metabolic groups absent in the query.",
  "evidence_gaps": [
    "No direct human absolute bioavailability data for the query molecule.",
    "Morgan similarities to evidence molecules are modest, limiting precise transferability.",
    "Human metabolic stability of the 2,6-dimethylpiperidine and pyridyl carbinol moieties is not directly evidenced.",
    "Solubility and BCS classification of the query are unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

